    public function testListDeliveries(): void
    {
        $this->queueJson(200, '{"count":1,"next":null,"previous":null,"results":[{"uuid":"11111111-2222-4333-8444-555555555555","kind":"SEND","status":"DELIVERED","rail":"NETWORK","created_at":"2026-11-01T10:00:00Z","delivered_at":"2026-11-01T10:00:01Z","detail_lines":["Send","Delivered"]}]}');

        $result = $this->client->transactions->travelRule->listDeliveries('transactionId-1', [
            'limit' => 1,
            'offset' => 1,
        ]);

        $request = $this->lastRequest();
        self::assertSame('GET', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/transactions/transactionId-1/travel-rule/deliveries/', $request->getUri()->getPath());
        self::assertSame([
            'limit' => '1',
            'offset' => '1',
        ], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('', (string) $request->getBody());
        self::assertCount(1, $result->results);
        self::assertContainsOnlyInstancesOf(Types\TravelRuleDeliveryLogEntry::class, $result->results);
        self::assertFalse($result->hasNextPage());
        self::assertSame($this->decoded('{"count":1,"next":null,"previous":null,"results":[{"uuid":"11111111-2222-4333-8444-555555555555","kind":"SEND","status":"DELIVERED","rail":"NETWORK","created_at":"2026-11-01T10:00:00Z","delivered_at":"2026-11-01T10:00:01Z","detail_lines":["Send","Delivered"]}]}'), $result->toArray());
    }

